}

.dd-pattern-stats {
  font-size: 12px;
  font-weight: 600;
  background: rgba(56, 189, 248, 0.15);
  border-color: rgba(56, 189, 248, 0.35);
}

options.helpers:
context.handlebars.registerHelper('splitQueryPatterns', function(query, dominantQuery, count1, count2) {
  const queryText = query || dominantQuery || '';
  const fallbackCount = count1 || count2;
  if (!queryText) return [];
  const text = String(queryText).trim();
  const headerRegex = /-- \[Pattern #(\d+)\s*\(([^)]+)\)\]\s*\n/g;
  const matches = [...text.matchAll(headerRegex)];
  if (matches.length > 0) {
    const results = [];
    for (let i = 0; i < matches.length; i++) {
      const match = matches[i];
      const patternNum = match[1];
      const stats = match[2];
      const startIndex = match.index + match[0].length;
      const endIndex = (i + 1 < matches.length) ? matches[i + 1].index : text.length;
      const sql = text.substring(startIndex, endIndex).trim();
      results.push({
        title: 'Pattern #' + patternNum,
        stats: stats,
        sql: sql
      });
    }
    return results;
  }
  const countStr = fallbackCount ? (fallbackCount + ' executions') : '';
  return [{
    title: 'Repeated Query',
    stats: countStr,
    sql: text
  }];
});
